    private static async Task<DataRow> CorrectionAsync(IUnitOfWork w,Guid project,Guid calculation,Guid correction,CancellationToken ct)
    {
        using var c=w.Command(@"SELECT R.*,I.PersonId,I.EmploymentId,I.PersonnelGroup,I.FinanceEntryId,I.LedgerId OriginalLedgerId,A.ApprovalId,A.ApprovedByAccountId
 FROM dbo.AccrualCorrections R WITH(UPDLOCK,HOLDLOCK) JOIN dbo.AccrualPostingItems I ON I.ItemId=R.SourceItemId JOIN dbo.AccrualPostings P ON P.PostingId=I.PostingId JOIN dbo.AccrualCalculations C ON C.CalculationId=P.CalculationId
 LEFT JOIN dbo.AccrualCorrectionApprovals A ON A.CorrectionId=R.CorrectionId WHERE R.CorrectionId=@id AND C.ProjectId=@project AND C.CalculationId=@calculation AND P.IsSealed=1");Id(c,"@id",correction);Id(c,"@project",project);Id(c,"@calculation",calculation);var rows=await c.TableAsync(ct);return rows.Rows.Count==1?rows.Rows[0]:throw new InvalidOperationException("Bu proje/hesapta mali düzeltme bulunamadı.");
    }
    private static async Task<DataRow> CorrectionSourceAsync(IUnitOfWork w,Guid project,Guid calculation,Guid item,CancellationToken ct)
    {
        using var c=w.Command(@"SELECT I.* FROM dbo.AccrualItemBalances I JOIN dbo.AccrualPostings P ON P.PostingId=I.PostingId JOIN dbo.AccrualCalculations C ON C.CalculationId=P.CalculationId WHERE I.ItemId=@id AND C.ProjectId=@project AND C.CalculationId=@calculation AND P.IsSealed=1 AND I.FinanceEntryId IS NOT NULL");Id(c,"@id",item);Id(c,"@project",project);Id(c,"@calculation",calculation);var rows=await c.TableAsync(ct);return rows.Rows.Count==1?rows.Rows[0]:throw new InvalidOperationException("Düzeltme için bu hesaptan aktarılmış pozitif mali satır seçin.");
    }
    private static void CurrentCorrection(DataRow source,DataRow request)
    {
        if(source.Field<Guid?>("LastCorrectionId")!=request.Field<Guid?>("PreviousCorrectionId")||source.Field<decimal>("EffectiveAmount")!=request.Field<decimal>("OldAmount"))throw new InvalidOperationException("Bu satıra başka düzeltme aktarılmış; güncel tutardan yeni düzeltme hazırlayın.");
    }
    private static async Task CorrectionIndependentAsync(IUnitOfWork w,Guid calculation,DataRow r,Guid actor,CancellationToken ct)
    {
        await IndependentAsync(w,calculation,actor,ct);
        using var c=w.Command("SELECT dbo.SameAccountPerson(@actor,@creator)");Id(c,"@actor",actor);Id(c,"@creator",r.Field<Guid>("CreatedByAccountId"));if(Convert.ToInt32(await c.ExecuteScalarAsync(ct))!=0)throw new InvalidOperationException("Düzeltmeyi hazırlayan kişi başka hesabıyla da onaylayamaz.");
    }
    internal async Task CreateCorrectionAsync(Wire.AccrualCorrectionCreate input,CancellationToken ct)
