        if(input.CorrectionId==Guid.Empty||input.NewAmount<0||input.NewAmount>9999999999999999.99m||decimal.Round(input.NewAmount,2)!=input.NewAmount||input.NewAmount==input.OldAmount)throw new ArgumentException("Yeni toplam sıfır veya pozitif, iki ondalıklı ve önceki tutardan farklı olmalı. Sıfır tam ters harekettir.");
        string explanation=AuditContext.ValidateReason(input.Reason);using var reason=AuditContext.UseReason(explanation);await using var w=await SqlUnitOfWork.OpenAsync(connectionString,ct);await AuthorizeAsync(w,input.ProjectId,true,ct);Guid actor=await ActorAsync(w,ct);byte[] hash=Payload(input);
        using(var old=w.Command("SELECT PayloadHash,CreatedByAccountId FROM dbo.AccrualCorrections WHERE CorrectionId=@id")){Id(old,"@id",input.CorrectionId);var rows=await old.TableAsync(ct);if(rows.Rows.Count>0){var r=rows.Rows[0];if(r.Field<Guid>("CreatedByAccountId")!=actor||!((byte[])r["PayloadHash"]).SequenceEqual(hash))throw new InvalidOperationException("Düzeltme işlem kimliği farklı içerikle kullanılmış.");await w.CommitAsync(ct);return;}}
        await ProjectFinanceService.DemandProjectAsync(w,input.ProjectId,ct);var source=await CorrectionSourceAsync(w,input.ProjectId,input.CalculationId,input.SourceItemId,ct);
        if(source.Field<Guid?>("LastCorrectionId")!=input.PreviousCorrectionId||source.Field<decimal>("EffectiveAmount")!=input.OldAmount)throw new InvalidOperationException("Seçili tutar değişmiş; listeyi yenileyin.");
        using var c=w.Command("INSERT dbo.AccrualCorrections(CorrectionId,SourceItemId,PreviousCorrectionId,OldAmount,NewAmount,Reason,CreatedByAccountId,CreatedBy,PayloadHash) VALUES(@id,@item,@previous,@old,@new,@reason,@actor,@name,@hash)");Id(c,"@id",input.CorrectionId);Id(c,"@item",input.SourceItemId);Id(c,"@previous",input.PreviousCorrectionId);Id(c,"@actor",actor);c.Money("@old",input.OldAmount);c.Money("@new",input.NewAmount);c.Text("@reason",explanation,500);c.Text("@name",user.Username);c.Parameters.Add("@hash",SqlDbType.Binary,32).Value=hash;await c.ExecuteNonQueryAsync(ct);await w.CommitAsync(ct);
    }
    internal async Task ApproveCorrectionAsync(Wire.AccrualCorrectionApprove input,CancellationToken ct)
