        if(input.ApprovalId==Guid.Empty)throw new ArgumentException("Onay kimliği gerekiyor.");using var reason=AuditContext.UseReason(AuditContext.ValidateReason(input.Reason));await using var w=await SqlUnitOfWork.OpenAsync(connectionString,ct);await AuthorizeAsync(w,input.ProjectId,true,ct);Guid actor=await ActorAsync(w,ct);var r=await CorrectionAsync(w,input.ProjectId,input.CalculationId,input.CorrectionId,ct);byte[] hash=Payload(input);
        if(!r.IsNull("ApprovalId")){using var old=w.Command("SELECT PayloadHash FROM dbo.AccrualCorrectionApprovals WHERE ApprovalId=@id AND CorrectionId=@correction AND ApprovedByAccountId=@actor");Id(old,"@id",input.ApprovalId);Id(old,"@correction",input.CorrectionId);Id(old,"@actor",actor);if(await old.ExecuteScalarAsync(ct) is byte[] bytes&&bytes.SequenceEqual(hash)){await w.CommitAsync(ct);return;}throw new InvalidOperationException("Bu düzeltme onaylanmış; geçmişi yenileyin.");}
        if(!((byte[])r["RecordVersion"]).SequenceEqual(PersonnelConcurrency.RequireVersion(input.Version)))throw new InvalidOperationException("Düzeltme seçimi değişmiş.");CurrentCorrection(await CorrectionSourceAsync(w,input.ProjectId,input.CalculationId,r.Field<Guid>("SourceItemId"),ct),r);await CorrectionIndependentAsync(w,input.CalculationId,r,actor,ct);
        using var c=w.Command("INSERT dbo.AccrualCorrectionApprovals(ApprovalId,CorrectionId,ApprovedByAccountId,ApprovedBy,PayloadHash) VALUES(@id,@correction,@actor,@name,@hash)");Id(c,"@id",input.ApprovalId);Id(c,"@correction",input.CorrectionId);Id(c,"@actor",actor);c.Text("@name",user.Username);c.Parameters.Add("@hash",SqlDbType.Binary,32).Value=hash;await c.ExecuteNonQueryAsync(ct);await w.CommitAsync(ct);
    }
    private static async Task<PostingPreview> CorrectionPreviewAsync(IUnitOfWork w,Guid project,Guid calculation,Guid correction,CancellationToken ct)
    {
        var r=await CorrectionAsync(w,project,calculation,correction,ct);var issues=new List<string>();CurrentCorrection(await CorrectionSourceAsync(w,project,calculation,r.Field<Guid>("SourceItemId"),ct),r);
        if(r.IsNull("ApprovalId"))issues.Add("Önce bağımsız düzeltme mali onayı gerekiyor.");else await CorrectionIndependentAsync(w,calculation,r,r.Field<Guid>("ApprovedByAccountId"),ct);
        await ProjectFinanceService.DemandProjectAsync(w,project,ct);await SchedulingRules.LockPersonAsync(w,r.Field<Guid>("PersonId"),ct);
        var group=(PersonnelGroup)r.Field<int>("PersonnelGroup");using var c=w.Command($@"SELECT C.PersonId,C.CurrentEmploymentId,C.RecordVersion PersonVersion,C.PARA Balance,C.ArchivedUtc,E.IsClosed,E.RecordVersion EmploymentVersion FROM {PersonnelRepository.Table(group)} C JOIN dbo.EmploymentPeriods E WITH(UPDLOCK,HOLDLOCK) ON E.EmploymentId=@employment AND E.PersonId=C.PersonId WHERE C.PersonId=@person");Id(c,"@person",r.Field<Guid>("PersonId"));Id(c,"@employment",r.Field<Guid>("EmploymentId"));var targets=await c.TableAsync(ct);targets.Columns.Add("Delta",typeof(decimal));targets.Columns.Add("AfterBalance",typeof(decimal));
        if(targets.Rows.Count!=1)issues.Add("Güncel personel kartı bulunamadı.");else{var t=targets.Rows[0];if(t.Field<Guid>("CurrentEmploymentId")!=r.Field<Guid>("EmploymentId")||!t.IsNull("ArchivedUtc")||t.Field<bool>("IsClosed"))issues.Add("Personel arşivde veya çalışma dönemi farklı; yeni döneme düzeltme yazılamaz.");decimal after=t.Field<decimal>("Balance")+r.Field<decimal>("Delta");t["Delta"]=r["Delta"];if(after is < -9999999999999999.99m or > 9999999999999999.99m)issues.Add("Bakiye sınırı aşılır.");else t["AfterBalance"]=after;}
        using(var allocated=w.Command("SELECT COALESCE(SUM(Amount),0) FROM dbo.ActivePaymentAllocations WHERE FinanceEntryId=@id")){Id(allocated,"@id",r.Field<Guid>("FinanceEntryId"));decimal total=Convert.ToDecimal(await allocated.ExecuteScalarAsync(ct));targets.Columns.Add("AllocatedAmount",typeof(decimal));foreach(DataRow t in targets.Rows)t["AllocatedAmount"]=total;if(r.Field<decimal>("NewAmount")<total)issues.Add("Yeni hakediş aktif tahsis toplamının altında; önce ödeme/avans tahsislerini serbest bırakın.");}
        targets.AcceptChanges();string fp=Convert.ToHexString(Payload(new{Project=project,Calculation=calculation,Correction=correction,Version=r["RecordVersion"],Approval=r["ApprovalId"],Targets=RemoteApi.Encode(targets),Issues=issues.ToArray()}));return new(r,targets,fp,issues.ToArray());
    }
