    {
        if(DesktopConnection.IsRemote(connectionString))return await RemoteApi.For(connectionString,user).SendAsync<Wire.AccrualPostingQuote>($"accrual/{project:D}/{calculation:D}/corrections/{correction:D}/quote",null,ct);
        await using var w=await SqlUnitOfWork.OpenAsync(connectionString,ct);await AuthorizeAsync(w,project,true,ct);var p=await CorrectionPreviewAsync(w,project,calculation,correction,ct);await w.CommitAsync(ct);return new(RemoteApi.Encode(p.Targets),p.Fingerprint,p.Issues.Length==0,p.Issues);
    }
