        using(var c=w.Command("INSERT dbo.AccrualCorrectionTransfers(TransferId,SourceItemId,PreviousCorrectionId,CorrectionId,ApprovalId,LedgerId,BeforeBalance,AfterBalance,PostedByAccountId,PostedBy,PayloadHash) VALUES(@id,@item,@previous,@correction,@approval,@ledger,@before,@after,@actor,@name,@hash)")){Id(c,"@id",input.TransferId);Id(c,"@item",r.Field<Guid>("SourceItemId"));Id(c,"@previous",r.Field<Guid?>("PreviousCorrectionId"));Id(c,"@correction",input.CorrectionId);Id(c,"@approval",r.Field<Guid>("ApprovalId"));Id(c,"@actor",actor);c.Parameters.Add("@ledger",SqlDbType.BigInt).Value=ledger;c.Money("@before",target.Field<decimal>("Balance"));c.Money("@after",target.Field<decimal>("AfterBalance"));c.Text("@name",user.Username);c.Parameters.Add("@hash",SqlDbType.Binary,32).Value=hash;await c.ExecuteNonQueryAsync(ct);}await w.CommitAsync(ct);
