    internal async Task<DataTable> CorrectionHistoryAsync(Guid project,Guid calculation,CancellationToken ct)
    {
        if(DesktopConnection.IsRemote(connectionString))return await RemoteApi.For(connectionString,user).TableAsync($"accrual/{project:D}/{calculation:D}/corrections",ct);
        await using var w=await SqlUnitOfWork.OpenAsync(connectionString,ct);await AuthorizeAsync(w,project,false,ct);using var c=w.Command(@"SELECT TOP(1000) R.*,I.LedgerId OriginalLedgerId,(SELECT Reference FROM dbo.FinanceEntries WHERE EntryId=I.FinanceEntryId) FinanceReference,(SELECT MIN(L.PersonCaption) FROM dbo.AccrualCalculationLines L WHERE L.CalculationId=C.CalculationId AND L.EmploymentId=I.EmploymentId) PersonCaption,A.ApprovalId,A.ApprovedBy,A.ApprovedUtc,T.TransferId,T.LedgerId,T.PostedBy,T.PostedUtc,CAST(CASE WHEN I.EffectiveAmount=R.OldAmount AND NOT EXISTS(SELECT I.LastCorrectionId EXCEPT SELECT R.PreviousCorrectionId) THEN 1 ELSE 0 END AS bit) IsCurrent
 FROM dbo.AccrualCorrections R JOIN dbo.AccrualItemBalances I ON I.ItemId=R.SourceItemId JOIN dbo.AccrualPostings P ON P.PostingId=I.PostingId JOIN dbo.AccrualCalculations C ON C.CalculationId=P.CalculationId LEFT JOIN dbo.AccrualCorrectionApprovals A ON A.CorrectionId=R.CorrectionId LEFT JOIN dbo.AccrualCorrectionTransfers T ON T.CorrectionId=R.CorrectionId WHERE C.ProjectId=@project AND C.CalculationId=@calculation ORDER BY R.CreatedUtc DESC,R.CorrectionId");Id(c,"@project",project);Id(c,"@calculation",calculation);var rows=await c.TableAsync(ct);await w.CommitAsync(ct);return rows;
    }
